-- Sample card-transactions database for Career Code School.
-- Everything here is made up. Generated by tools/make-bank-db.py.

CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  city TEXT NOT NULL,
  joined_on TEXT NOT NULL
);
CREATE TABLE cards (
  id INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(id),
  last4 TEXT NOT NULL,
  type TEXT NOT NULL,          -- 'debit' or 'credit'
  status TEXT NOT NULL,        -- 'active', 'blocked' or 'expired'
  expires TEXT NOT NULL        -- 'YYYY-MM'
);
CREATE TABLE transactions (
  id INTEGER PRIMARY KEY,
  card_id INTEGER NOT NULL REFERENCES cards(id),
  merchant TEXT NOT NULL,
  category TEXT NOT NULL,
  amount REAL NOT NULL,        -- in pounds, e.g. 12.50
  currency TEXT NOT NULL,
  status TEXT NOT NULL,        -- 'approved', 'declined' or 'refunded'
  created_at TEXT NOT NULL     -- 'YYYY-MM-DD HH:MM'
);
CREATE TABLE disputes (
  id INTEGER PRIMARY KEY,
  transaction_id INTEGER NOT NULL REFERENCES transactions(id),
  reason TEXT NOT NULL,
  status TEXT NOT NULL,        -- 'opened', 'under_review', 'resolved_won' or 'resolved_lost'
  opened_on TEXT NOT NULL
);




